from __future__ import annotations
from dataclasses import dataclass
from typing import Sequence, Iterable


def first_moment(weights: Sequence[float]) -> float:
    return float(sum(weights))


def second_moment(weights: Sequence[float]) -> float:
    return float(sum(w * w for w in weights))


def support_condition_holds(weights: Sequence[float], on_line: Iterable[int]) -> bool:
    on = set(on_line)
    return all(w == 0.0 for i, w in enumerate(weights) if i not in on)


def certify_proportion(weights: Sequence[float], on_line: Sequence[int]) -> dict:
    """Verify the mollified-moment hypotheses and certify proportion >= 1/9."""
    n = len(weights)
    k = len(set(on_line))
    m1 = first_moment(weights)
    m2 = second_moment(weights)
    support_ok = support_condition_holds(weights, on_line)
    moment_ok = (1.0 / 9.0) * m2 * n <= m1 * m1 + 1e-12
    certified = support_ok and moment_ok and m2 > 0 and n > 0
    return {
        "N": n, "onLine": k, "M1": m1, "M2": m2,
        "support_ok": support_ok, "moment_ineq_ok": moment_ok,
        "certified_lower_bound": 1.0 / 9.0 if certified else 0.0,
        "observed_proportion": k / n if n else 0.0,
    }


if __name__ == "__main__":
    # total = {0,1}, onLine = {0}, w = [1, 0]  (non-vacuity witness)
    print(certify_proportion([1.0, 0.0], [0]))

from __future__ import annotations
from typing import Sequence


def cauchy_schwarz_deficit(nonzero_weights: Sequence[float]) -> float:
    """c = variance/mean^2 of the on-line weights; proportion beats 1/9 by (1+c)."""
    k = len(nonzero_weights)
    if k == 0:
        return 0.0
    mu = sum(nonzero_weights) / k
    if mu == 0.0:
        return 0.0
    var = sum((w - mu) ** 2 for w in nonzero_weights) / k
    return var / (mu * mu)


def improved_bound(nonzero_weights: Sequence[float]) -> float:
    return (1.0 / 9.0) * (1.0 + cauchy_schwarz_deficit(nonzero_weights))


if __name__ == "__main__":
    for name, w in {
        "flat": [1, 1, 1, 1],
        "mild": [1.0, 1.2, 0.8, 1.5],
        "heavy": [0.2, 3.0, 0.1, 2.7],
    }.items():
        print(f"{name:6s}: c={cauchy_schwarz_deficit(w):.3f}  "
              f"improved={improved_bound(w):.4f}")

