function CERTIFY(w[0..N-1], onLine):
    M1 <- 0 ; M2 <- 0 ; support_ok <- true
    for i in 0..N-1:
        M1 <- M1 + w[i]
        M2 <- M2 + w[i]*w[i]
        if i not in onLine and w[i] != 0: support_ok <- false
    moment_ok <- (1/9)*M2*N <= M1*M1
    if support_ok and moment_ok and M2 > 0 and N > 0:
        return 1/9            # proven lower bound
    else:
        return 0              # hypotheses not met

function IMPROVED_CONSTANT(w_online[0..k-1], d):
    base <- 1 / d^2
    if k == 0: return base
    mu  <- mean(w_online)
    if mu == 0: return base
    var <- mean((w_online - mu)^2)
    c   <- var / mu^2
    return base * (1 + c)

function POOLED_BOUND(family = [(N_b, onLine_b)], d):
    base <- 1 / d^2
    tot <- 0 ; onl <- 0 ; certified <- true
    for (N_b, onLine_b) in family:
        tot <- tot + N_b
        onl <- onl + onLine_b
        if onLine_b < base * N_b: certified <- false
    return (onl / tot, certified)
